```nginx
# /etc/nginx/conf.d/app.conf
server {
    listen 80;
    server_name app.x.com;
    root /var/www/app;

    location / {
        try_files $uri $uri/ /index.html;     # SPA
    }
    location /static/ {
        expires 30d;
        access_log off;
    }
}
```
- Ubuntu: `sites-available/` + symlink `sites-enabled/`; RHEL: `conf.d/*.conf`.
- location ustuvorligi: `=` aniq > `^~` prefix > `~`/`~*` regex (birinchi mos) > eng uzun prefix.
- `server_name` mos kelmasa — `default_server` (yoki birinchi) javob beradi.

31372.a:
```nginx
upstream api_backend {
    server 127.0.0.1:8080 max_fails=3 fail_timeout=10s;
    server 127.0.0.1:8081;
    keepalive 64;
}
server {
    listen 80;
    server_name api.x.com;
    return 301 https://$host$request_uri;
}
server {
    listen 443 ssl http2;
    server_name api.x.com;
    ssl_certificate     /etc/letsencrypt/live/api.x.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/api.x.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    add_header Strict-Transport-Security "max-age=31536000" always;
    client_max_body_size 20m;

    location / {
        proxy_pass http://api_backend;
        proxy_http_version 1.1;
        proxy_set_header Connection "";          # upstream keepalive uchun
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_connect_timeout 3s;
        proxy_read_timeout 60s;
    }
    location /ws {
        proxy_pass http://api_backend;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}
```
Gotcha: `proxy_pass http://b/;` (oxirida `/`) — location prefiksini kesib tashlaydi; `proxy_pass http://b;` — URI'ni o'zgarishsiz uzatadi.

31374.a:
```nginx
worker_processes auto;
worker_rlimit_nofile 100000;
events { worker_connections 8192; }

http {
    server_tokens off;
    sendfile on; tcp_nopush on;
    keepalive_timeout 30s;
    client_body_timeout 10s; client_header_timeout 10s;   # slowloris

    gzip on; gzip_types application/json text/css application/javascript;

    limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;
    limit_conn_zone $binary_remote_addr zone=perip:10m;

    proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=c:50m max_size=2g inactive=10m;

    server {
        location /api/ {
            limit_req zone=api burst=20 nodelay;
            limit_conn perip 50;
            limit_req_status 429;
            proxy_pass http://api_backend;
        }
        location /public/ {
            proxy_cache c;
            proxy_cache_valid 200 5m;
            proxy_cache_use_stale error timeout updating;
            add_header X-Cache $upstream_cache_status;
            proxy_pass http://api_backend;
        }
    }
}
```
Max ulanish ~ `worker_processes * worker_connections` (proxy'da har client 2 FD). Limitlar FD limiti bilan mos bo'lsin.
Status: `stub_status` -> nginx-prometheus-exporter (active, reading, writing, waiting).
Gotcha: LB orqasida `$binary_remote_addr` = LB IP — hamma bitta limitga tushadi; `real_ip_header X-Forwarded-For` + `set_real_ip_from`.
